package mask

import (
	_ "embed"
	"strings"
	"unicode"
)

// Derived public reference (see docs/structures.md). Data files GENERATED by measurement on the
// machine's public material (TestGeneratePublicRef, in vocab_generate_test.go), never written by
// hand. The header of each one says where, when and with which criterion it was generated.
//
//   - public_ref.txt: words that appear in a resource name position (value of a type key
//     in YAML/JSON/TOML/INI, --type option, name after FROM/JOIN/INTO/SCHEMA in SQL) in
//     many distinct public projects (default, public, dbo, api, app...). They are too
//     generic for the conversation memory: masked where a rule decided them, never
//     propagated (Decision.Generic, isGeneric).
//   - official_images.txt: the Docker Official Images (redis, postgres, nginx...), the
//     folders of the public docker-library/docs repository (one per image, with content.md and
//     metadata.json). Only an image from this list, without an organization, proves that the
//     service with the same name is the software (textSoftware); a local image ("image: api-x" with build:) does not.
//   - public_software.txt and vendors.txt: name and owner of GitHub's popular public
//     repositories. In the image rule, org/name only stays in plain text with both keys: vendor
//     organization and public software name.
//   - language_types.txt: the vocabulary's data types (vocab_types.go) that public Go code
//     uses as a field or variable type ("name    type", the same shape as a
//     schema). In a "name    type" block, these types alone do not decide it is a schema (the
//     schema reader asks for a type only data uses: object, category, datetime64[ns], VARCHAR(n)).

//go:embed data/public_ref.txt
var publicRefTxt string

//go:embed data/language_types.txt
var languageTypesTxt string

//go:embed data/official_images.txt
var officialImagesTxt string

//go:embed data/public_software.txt
var publicSoftwareTxt string

//go:embed data/vendors.txt
var vendorsTxt string

// publicSoftware and vendors: name and owner of GitHub's popular repositories (measured;
// normSoftware). They only count together (publicPath): alone, the list of names includes
// codenames.
var publicSoftware, vendors map[string]bool

// officialImages: names of the Docker Official Images (measured; lowercase).
var officialImages map[string]bool

// languageTypes: data types that are also language types (measured; lowercase).
var languageTypes map[string]bool

func init() {
	publicRef = readGeneratedList(publicRefTxt)
	languageTypes = readGeneratedList(languageTypesTxt)
	officialImages = readGeneratedList(officialImagesTxt)
	publicSoftware = readGeneratedList(publicSoftwareTxt)
	vendors = readGeneratedList(vendorsTxt)
}

// readGeneratedList: one word per line (lowercase); "#" starts a comment (the header).
func readGeneratedList(txt string) map[string]bool {
	m := map[string]bool{}
	for _, l := range strings.Split(txt, "\n") {
		if l = strings.TrimSpace(l); l != "" && l[0] != '#' {
			m[strings.ToLower(l)] = true
		}
	}
	return m
}

// normSoftware: the name as the GitHub lists store it (lowercase, without - _ .): Docker Hub writes
// "prometheuscommunity/postgres-exporter" and GitHub "prometheus-community/postgres_exporter".
func normSoftware(v string) string {
	return strings.Map(func(r rune) rune {
		switch r {
		case '-', '_', '.':
			return -1
		}
		return unicode.ToLower(r)
	}, v)
}

// publicOrg and publicName: the two keys of the public image (publicPath, textSoftware).
func publicOrg(org string) bool {
	return publicRef[strings.ToLower(org)] || vendors[normSoftware(org)]
}

// publicName: the whole name is public software or, piece by piece, each piece is software, a
// reference word, a role, a type or a version, and at least one is software (clickhouse-server,
// statsd-exporter, node-chrome). An unknown piece blocks (payments-api, cp-kafka).
func publicName(name string) bool {
	l := strings.ToLower(name)
	if officialImages[l] || publicRef[l] || publicSoftware[normSoftware(name)] {
		return true
	}
	ps := valuePieces(name)
	if len(ps) < 2 || len(ps) > 6 {
		return false
	}
	sw := false
	for _, p := range ps {
		switch {
		case officialImages[p] || publicSoftware[p]:
			sw = true
		case isDigit(p[0]) || len(p) <= 2 && p[0] == 'v' || publicRef[p] || roleVocab[p] || typeVocab[p]:
		default:
			return false
		}
	}
	return sw
}
